import { NextResponse } from 'next/server'
import { deleteProduct, getProductBySlug, updateProduct } from '@/lib/queries'
import { fieldErrors, productSchema } from '@/lib/validation'

/**
 * /api/products/:slug
 *
 * NOTE: params is a Promise here too (Next.js 16), so every handler awaits it.
 * RouteContext<'/api/products/[slug]'> is generated by `next typegen`.
 */

// GET one product → 200 or 404
export async function GET(_request: Request, ctx: RouteContext<'/api/products/[slug]'>) {
  const { slug } = await ctx.params
  const product = await getProductBySlug(slug)

  if (!product) {
    return NextResponse.json({ error: `No product with slug "${slug}"` }, { status: 404 })
  }

  return NextResponse.json(product)
}

// PATCH → update. 200 with the updated row, 400 on bad input, 404 if it doesn't exist
export async function PATCH(request: Request, ctx: RouteContext<'/api/products/[slug]'>) {
  const { slug } = await ctx.params
  const existing = await getProductBySlug(slug)

  if (!existing) {
    return NextResponse.json({ error: `No product with slug "${slug}"` }, { status: 404 })
  }

  const body = await request.json().catch(() => null)
  if (!body) {
    return NextResponse.json({ error: 'The body must be valid JSON' }, { status: 400 })
  }

  // PATCH = partial update, so every field is optional. partial() gives us that for free
  const parsed = productSchema.partial().safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: 'Validation failed', fields: fieldErrors(parsed.error) }, { status: 400 })
  }

  // Merge: start from what's in the database, overwrite with the fields that were sent
  const merged = {
    name: existing.name,
    slug: existing.slug,
    description: existing.description,
    price: Number(existing.price), // decimal comes back as a string
    categoryId: existing.categoryId,
    inStock: existing.inStock,
    ...parsed.data,
  }

  const updated = await updateProduct(existing.id, merged)

  return NextResponse.json(updated)
}

// DELETE → 204 No Content (nothing to send back)
export async function DELETE(_request: Request, ctx: RouteContext<'/api/products/[slug]'>) {
  const { slug } = await ctx.params
  const existing = await getProductBySlug(slug)

  if (!existing) {
    return NextResponse.json({ error: `No product with slug "${slug}"` }, { status: 404 })
  }

  await deleteProduct(existing.id)

  return new NextResponse(null, { status: 204 })
}
